import unittest
from candidate import filter_by_prefix

class TestFilterByPrefix(unittest.TestCase):
    def test_filter_empty_list(self):
        self.assertEqual(filter_by_prefix([], 'a'), [])

    def test_filter_with_empty_prefix(self):
        self.assertEqual(filter_by_prefix(['abc', 'def'], ''), ['abc', 'def'])

    def test_filter_normal_case_prefix_match(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde', 'array'], 'a'), ['abc', 'array'])

    def test_filter_normal_case_prefix_no_match(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde', 'array'], 'x'), [])

    def test_filter_case_sensitivity(self):
        self.assertEqual(filter_by_prefix(['Apple', 'apple', 'Banana'], 'a'), ['Apple', 'apple'])

    def test_filter_with_case_sensitive_prefix(self):
        self.assertEqual(filter_by_prefix(['apple', 'Apple', 'Banana'], 'A'), ['Apple'])

    def test_filter_with_multiple_prefix_matches(self):
        self.assertEqual(filter_by_prefix(['apple', 'apricot', 'applesauce', 'banana'], 'ap'), ['apple', 'apricot', 'applesauce'])

    def test_filter_with_longer_strings(self):
        self.assertEqual(filter_by_prefix(['apricot', 'apples', 'apricot sauce', 'banana'], 'ap'), ['apricot', 'apples', 'apricot sauce'])

    def test_filter_with_prefix_at_end(self):
        self.assertEqual(filter_by_prefix(['prefixabc', 'prefixdef', 'abc'], 'prefix'), ['prefixabc', 'prefixdef'])

    def test_filter_with_prefix_not_at_start(self):
        self.assertEqual(filter_by_prefix(['prefixabc', 'abc', 'def'], 'abc'), ['abc'])

    def test_filter_with_none_prefix(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(['abc', 'def'], None)

    def test_filter_with_none_strings(self):
        self.assertEqual(filter_by_prefix([None, 'abc', None], 'a'), [])

    def test_filter_with_mixed_types(self):
        with self.assertRaises(TypeError):
            filter_by_prefix([123, 'abc'], 'a')

    def test_filter_with_non_string_prefix(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(['abc', 'def'], 123)

    def test_filter_with_non_string_strings(self):
        with self.assertRaises(TypeError):
            filter_by_prefix([123, 456], 'a')

    def test_filter_with_empty_string_list(self):
        self.assertEqual(filter_by_prefix([''], 'a'), [])

    def test_filter_with_single_string(self):
        self.assertEqual(filter_by_prefix(['apple'], 'a'), ['apple'])

    def test_filter_with_partial_prefix_match(self):
        self.assertEqual(filter_by_prefix(['apple', 'apricot', 'apples'], 'ap'), ['apple', 'apricot', 'apples'])

    def test_filter_with_whitespace_prefix(self):
        self.assertEqual(filter_by_prefix([' apple', 'b apple', 'c'], ' '), [' apple'])

    def test_filter_with_whitespace_strings(self):
        self.assertEqual(filter_by_prefix([' apple', 'b apple', 'c'], 'b'), ['b apple'])
